package pool

import (
    "context"
    "sync"
)

type Task func(ctx context.Context) error

type Pool struct {
    workers int
    tasks   chan Task
    wg      sync.WaitGroup
}

func NewPool(workers int, queueSize int) *Pool {
    if workers <= 0 { workers = 1 }
    return &Pool{
        workers: workers,
        tasks:   make(chan Task, queueSize),
    }
}

func (p *Pool) Start(ctx context.Context) {
    for i := 0; i < p.workers; i++ {
        p.wg.Add(1)
        go func() {
            defer p.wg.Done()
            for {
                select {
                case <-ctx.Done():
                    return
                case task, ok := <-p.tasks:
                    if !ok { return }
                    _ = task(ctx)
                }
            }
        }()
    }
}

func (p *Pool) Submit(t Task) bool {
    select {
    case p.tasks <- t:
        return true
    default:
        return false
    }
}

func (p *Pool) Stop() {
    close(p.tasks)
    p.wg.Wait()
}

