package cmap

import (
    "hash/fnv"
    "sync"
)

const ShardCount = 32

type MapShard struct {
    mu    sync.RWMutex
    items map[string]any
}

type ConcurrentMap struct {
    shards [ShardCount]*MapShard
}

func New() *ConcurrentMap {
    cm := &ConcurrentMap{}
    for i := 0; i < ShardCount; i++ {
        cm.shards[i] = &MapShard{items: make(map[string]any)}
    }
    return cm
}

func (m *ConcurrentMap) getShard(key string) *MapShard {
    h := fnv.New32a()
    _, _ = h.Write([]byte(key))
    return m.shards[h.Sum32()%ShardCount]
}

func (m *ConcurrentMap) Set(key string, val any) {
    shard := m.getShard(key)
    shard.mu.Lock()
    shard.items[key] = val
    shard.mu.Unlock()
}

func (m *ConcurrentMap) Get(key string) (any, bool) {
    shard := m.getShard(key)
    shard.mu.RLock()
    val, ok := shard.items[key]
    shard.mu.RUnlock()
    return val, ok
}

