package ratelimit

import (
    "sync"
    "time"
)

type Limiter struct {
    mu         sync.Mutex
    rate       float64
    capacity   float64
    tokens     float64
    lastRefill time.Time
}

func NewLimiter(ratePerSec float64, burstCapacity float64) *Limiter {
    return &Limiter{
        rate:       ratePerSec,
        capacity:   burstCapacity,
        tokens:     burstCapacity,
        lastRefill: time.Now(),
    }
}

func (l *Limiter) TryAcquire(tokens float64) bool {
    l.mu.Lock()
    defer l.mu.Unlock()

    now := time.Now()
    elapsed := now.Sub(l.lastRefill).Seconds()
    l.lastRefill = now

    l.tokens += elapsed * l.rate
    if l.tokens > l.capacity {
        l.tokens = l.capacity
    }

    if l.tokens >= tokens {
        l.tokens -= tokens
        return true
    }
    return false
}

