package packet

import (
    "encoding/binary"
    "errors"
    "hash/crc32"
    "io"
)

const Magic = 0x50414354 // 'PACT'
const MaxPayloadSize = 1 << 20 // 1MB

var (
    ErrBadMagic    = errors.New("invalid magic header")
    ErrPayloadHuge = errors.New("payload exceeds max size")
    ErrBadChecksum = errors.New("checksum mismatch")
)

type Packet struct {
    Payload []byte
}

func Decode(r io.Reader) (*Packet, error) {
    var header [12]byte
    if _, err := io.ReadFull(r, header[:]); err != nil {
        return nil, err
    }

    magic := binary.BigEndian.Uint32(header[0:4])
    if magic != Magic { return nil, ErrBadMagic }

    length := binary.BigEndian.Uint32(header[4:8])
    if length > MaxPayloadSize { return nil, ErrPayloadHuge }

    checksum := binary.BigEndian.Uint32(header[8:12])

    payload := make([]byte, length)
    if _, err := io.ReadFull(r, payload); err != nil {
        return nil, err
    }

    computed := crc32.ChecksumIEEE(payload)
    if computed != checksum {
        return nil, ErrBadChecksum
    }

    return &Packet{Payload: payload}, nil
}

